fn parse_range_expr(s: &str) -> Result<FieldRange, String> {
    // s like "2", "-1", "2..", "..3", "2..3", "..", "2..-1" etc, also "1.."?? original allowed "2.." meaning 2 to end.
    // Also "1..2" range, "..2", "2..", "..", etc.
    // For single numbers, start=end = that number
    // For ranges containing ".."
    if s.is_empty() {
        return Err(format!("invalid format: {}", s));
    }
    if s.contains("..") {
        let parts: Vec<&str> = s.split("..").collect();
        if parts.len() != 2 {
            return Err(format!("invalid format: {}", s));
        }
        let left = parts[0];
        let right = parts[1];
        let start = if left.is_empty() { None } else { Some(parse_isize(left)?) };
        let end = if right.is_empty() { None } else { Some(parse_isize(right)?) };
        // Validate: 0 not allowed
        if let Some(v) = start {
            if v == 0 {
                return Err(format!("invalid format: {}", s));
            }
        }
        if let Some(v) = end {
            if v == 0 {
                return Err(format!("invalid format: {}", s));
            }
        }
        // For range like 1..0 invalid due to 0
        // Also need to check if range like "1..0" invalid format as seen earlier for 1..0 => invalid format
        // The earlier error for 1..0 was invalid format, not due to 0? Actually 0 invalid, but also need to handle.
        // For ".." alone: both None => means all fields
        Ok(FieldRange { start, end })
    } else {
        // single
        let v = parse_isize(s)?;
        if v == 0 {
            return Err(format!("invalid format: {}", s));
        }
        Ok(FieldRange { start: Some(v), end: Some(v) })
    }
}

fn parse_isize(s: &str) -> Result<isize, String> {
    s.parse::<isize>().map_err(|_| format!("invalid format: {}", s))
}

fn parse_field_list(s: &str) -> Result<Vec<FieldRange>, String> {
    // comma-separated list of field index expressions
    if s.is_empty() {
        return Err(format!("invalid format: {}", s));
    }
    let mut res = Vec::new();
    // split by ',' but not inside? simple split
    for part in s.split(',') {
        if part.is_empty() {
            // invalid like "1,,2"
            return Err(format!("invalid format: {}", s));
        }
        res.push(parse_range_expr(part.trim())?);
    }
    Ok(res)
}

