fn parse_scheme(s: &str) -> Result<Scheme, String> {
    match s {
        "default" => Ok(Scheme::Default),
        "path" => Ok(Scheme::Path),
        "history" => Ok(Scheme::History),
        "" => Err(format!("invalid scoring scheme:  (expected: default|path|history)")),
        _ => Err(format!("invalid scoring scheme: {} (expected: default|path|history)", s)),
    }
}

fn parse_algo(s: &str) -> Result<Algo, String> {
    match s {
        "v1" => Ok(Algo::V1),
        "v2" => Ok(Algo::V2),
        "" => Err(format!("invalid algorithm (expected: v1 or v2)")),
        _ => Err(format!("invalid algorithm (expected: v1 or v2)")),
    }
}

fn parse_tiebreak(s: &str) -> Result<Vec<Tiebreak>, String> {
    if s.is_empty() {
        return Err(format!("invalid sort criterion:"));
    }
    let mut seen = std::collections::HashSet::new();
    let mut res = Vec::new();
    for part in s.split(',') {
        let p = part.trim();
        if p.is_empty() {
            return Err(format!("invalid sort criterion:"));
        }
        let tb = match p {
            "length" => Tiebreak::Length,
            "chunk" => Tiebreak::Chunk,
            "pathname" => Tiebreak::Pathname,
            "begin" => Tiebreak::Begin,
            "end" => Tiebreak::End,
            "index" => Tiebreak::Index,
            _ => return Err(format!("invalid sort criterion: {}", p)),
        };
        if !seen.insert(p.to_string()) {
            return Err(format!("duplicate sort criteria: {}", p));
        }
        res.push(tb);
    }
    // check index not at end
    if let Some(pos) = res.iter().position(|x| *x == Tiebreak::Index) {
        if pos != res.len()-1 {
            return Err(format!("index should be the last criterion"));
        }
    }
    Ok(res)
}

