fn extract_field_ranges(fields: &[String], ranges: &[FieldRange]) -> Vec<String> {
    let n = fields.len() as isize;
    let mut selected = Vec::new();
    for r in ranges {
        let start = r.start;
        let end = r.end;
        // Determine actual start index (0-based)
        // Cases:
        // - single: start==end==Some(k)
        // - range with start None, end None means all fields
        // - start Some, end None means start..end
        // - start None, end Some means ..end
        // - both Some means start..end inclusive? The spec says range [BEGIN]..[END] inclusive.
        // Also negative indices: -1 means last field, -2 second last, etc.
        // Need to convert to 0-based inclusive range.

        let (s_idx, e_idx) = match (start, end) {
            (Some(s), Some(e)) => {
                let s_abs = if s>0 { s-1 } else { n + s };
                let e_abs = if e>0 { e-1 } else { n + e };
                (s_abs, e_abs)
            },
            (Some(s), None) => {
                let s_abs = if s>0 { s-1 } else { n + s };
                (s_abs, n-1)
            },
            (None, Some(e)) => {
                let e_abs = if e>0 { e-1 } else { n + e };
                (0, e_abs)
            },
            (None, None) => {
                (0, n-1)
            }
        };
        // Now s_idx..=e_idx inclusive, but need to handle direction? If s_idx <= e_idx, iterate forward, else reverse?
        // In fzf, range 2..1? Probably invalid? But we handle both directions: if s_idx <= e_idx, take s_idx..=e_idx, else s_idx..=e_idx reversed? Actually range  -1..-2 maybe? Let's support both.
        if s_idx <= e_idx {
            for idx in s_idx..=e_idx {
                if idx>=0 && idx < n {
                    selected.push(fields[idx as usize].clone());
                }
            }
        } else {
            // reverse range
            for idx in (e_idx..=s_idx).rev() {
                if idx>=0 && idx < n {
                    selected.push(fields[idx as usize].clone());
                }
            }
        }
    }
    selected
}

