// Template handling for with-nth and accept-nth
// Templates contain placeholders like {1}, {2..}, {n}, {+n}, etc, and also literal text.
// Example: "Index: {n}, 1st: {1}"
// We need to parse template string and replace placeholders with actual values.

fn parse_template(template: &str, fields: &[String], index: usize, delimiter_str: &Option<String>, original_line: &str) -> String {
    // Replace placeholders
    let mut result = String::new();
    let mut chars = template.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '{' {
            // find closing }
            let mut inner = String::new();
            let mut found_close = false;
            while let Some(cc) = chars.next() {
                if cc == '}' {
                    found_close = true;
                    break;
                } else {
                    inner.push(cc);
                }
            }
            if !found_close {
                // no closing, treat as literal
                result.push('{');
                result.push_str(&inner);
                continue;
            }
            // inner is placeholder spec, e.g., "n", "+n", "1", "2..", "1..2", etc
            let replacement = eval_placeholder(&inner, fields, index, delimiter_str, original_line);
            result.push_str(&replacement);
        } else if c == '\\' {
            // escape? Need to check if backslash escapes placeholder?
            // In fzf, you can escape placeholder by prepending backslash.
            // So \{ should be literal {.
            if let Some(&next) = chars.peek() {
                if next == '{' || next == '}' || next == '\\' {
                    result.push(next);
                    chars.next();
                } else {
                    result.push(c);
                }
            } else {
                result.push(c);
            }
        } else {
            result.push(c);
        }
    }
    result
}

