    // Check for + prefix meaning? The docs say {+n} etc for multi-select? For single line, + means all selected? But in filter mode, + may mean all? Let's simplify.
    let mut s = inner;
    let mut plus = false;
    if s.starts_with('+') {
        plus = true;
        s = &s[1..];
    }
    if s == "n" {
        // zero-based ordinal index
        return index.to_string();
    }
    if s == "q" {
        // query? Not applicable for with-nth? Might be empty.
        return String::new();
    }
    // Try to parse as field range (may be range like 1..2 or single)
    // Could also be like "1,2"? But inside {} you can have {1..2} or {1,2}? The doc says template can contain field index expressions in curly braces. Example: '{n},{1},{3},{2},{1..2}' -> each brace contains one expression, not comma-separated inside one brace.
    // So inside brace, it should be single range expression, not list.
    match parse_range_expr(s) {
        Ok(r) => {
            let selected = extract_field_ranges(fields, &[r]);
            // Join selected fields similarly as before?
            // For template, the trailing delimiter is stripped from each expression, giving more control.
            // So we should join with delimiter_str? For template, they say trailing delimiter is stripped from each expression.
            // That suggests if you have {1..2} with delimiter ":", the result would be "a:b" but trailing delimiter stripped? Already joined without trailing delimiter.
            // So join similarly.
            join_fields(&selected, delimiter_str, original_line)
        },
        Err(_) => {
