fn char_bonus(prev_char: Option<char>, curr_char: char, scheme: Scheme) -> i32 {
    // Returns bonus for matching at curr_char position, given prev char
    // This is called when we match pattern char at this position
    // Bonus should be higher for boundaries

    // For history scheme, no bonus
    if scheme == Scheme::History {
        return 0;
    }

    if prev_char.is_none() {
        // start of string
        // Bonus for start? Might be high
        // For default, start bonus similar to boundary?
        return 10; // arbitrary
    }

    let prev = prev_char.unwrap();

    // Path scheme: only bonus after path separator / and \
    if scheme == Scheme::Path {
        if prev == '/' || prev == '\\' {
            return 10;
        } else {
            return 0;
        }
    }

    // Default scheme:
    // Check if prev is whitespace -> highest bonus
    if prev.is_whitespace() {
        return 10;
    }
    if prev == '/' {
        return 9;
    }
    // Group: : ; , |  maybe also / already handled
    if prev == ':' || prev == ';' || prev == ',' || prev == '|' {
        return 8;
    }
    // Non-word? Let's consider -, _, ., !, @, #, $, %, ^, &, *, (, ), +, =, {, }, [, ], ', ", <, >, ?, `, ~, \, etc
    // For these, maybe bonus 5? Or lower than delimiter group but higher than no bonus
