        // Let's attempt to give backslash slightly higher than others? Maybe backslash considered path separator? But in default, backslash is low, but still higher than dash? Let's assign:
        if prev == '\\' {
            return 7;
        }
        if prev == '-' || prev == '_' || prev == '.' {
            return 5;
        }
        // others: !@#$ etc
        return 4;
    }

    // CamelCase: if prev is lower and curr is upper
    if prev.is_ascii_lowercase() && curr_char.is_ascii_uppercase() {
