// Fuzzy matching scoring: we need to find best score for pattern matching text
// Implementation of fzf v2 algorithm: DP with bonus and penalty for gaps

fn fuzzy_match(pattern: &str, text: &str, case_sensitive: bool, scheme: Scheme) -> Option<(i32, usize, usize)> {
    // Returns Some((score, begin_index, end_index)) if matches, else None
    // begin = first matched char index, end = last matched char index
    // For scoring, we need to implement optimal matching

    if pattern.is_empty() {
        return Some((0, 0, 0));
    }

    let pat_chars: Vec<char> = if case_sensitive {
        pattern.chars().collect()
    } else {
        pattern.to_lowercase().chars().collect()
    };
    let text_chars: Vec<char> = text.chars().collect();
    let text_lower: Vec<char> = if case_sensitive {
        text_chars.clone()
    } else {
        text.to_lowercase().chars().collect()
    };

    let m = pat_chars.len();
    let n = text_chars.len();

    if m > n {
        // still possible if fuzzy? No, need at least m chars
        // but for fuzzy, pattern length must be <= text length for subsequence
        // Quick check: if pattern longer than text, no match
        if pat_chars.len() > text_chars.len() {
            return None;
        }
    }

    // DP arrays: we need to compute best score for matching up to i pattern chars ending at j text position
    // Let's implement classic fzf scoring:
    // score matrix: dp[i][j] = best score for matching pat[0..i] ending at text[j]
    // But we need efficient.

    // Simplify: we will do recursion with memo? Might be heavy for long texts but okay for filter mode (millions items but each short)

    // Let's implement iterative DP:
    // Initialize dp for first char: find all positions where pat[0] matches text
    // For each such position j, score = bonus for that position + (if j==0 then bonus for start)

    // For subsequent pattern chars i, we need to find best previous match k < j where dp[i-1][k] is valid, and compute score = dp[i-1][k] + bonus for gap + bonus for current char + consecutive bonus if k+1==j

    // Gap penalty: if there is gap between matches, penalty proportional to gap? fzf has scoreGapStart and scoreGapExtension

    // Let's attempt to implement similar to fzf's algorithm from memory:
    // Constants:
    const SCORE_MATCH: i32 = 16;
    const SCORE_GAP_START: i32 = -3;
    const SCORE_GAP_EXTENSION: i32 = -1;
    const BONUS_BOUNDARY: i32 = 8; // base for boundary? But we have variable bonus
    const BONUS_CONSECUTIVE: i32 = 8; // maybe?
    const BONUS_FIRST_CHAR_MULTIPLIER: i32 = 2;

    // But we have variable bonus from char_bonus that already includes boundary bonus.

    // We'll need to compute bonus for each text position
    let mut bonuses: Vec<i32> = Vec::with_capacity(n);
    for j in 0..n {
        let prev = if j==0 { None } else { Some(text_chars[j-1]) };
        let b = char_bonus(prev, text_chars[j], scheme);
        bonuses.push(b);
    }

    // DP: we need best score for each position for current pattern index
    // We'll keep vector of (score, begin)
    // For first pattern char
    let mut prev_dp: Vec<Option<(i32, usize)>> = vec![None; n]; // for i-1
    // For i=0
    for j in 0..n {
        if pat_chars[0] == text_lower[j] {
            let bonus = bonuses[j];
            let mut score = SCORE_MATCH + bonus;
            // first char multiplier?
            if j==0 {
                score += bonus * BONUS_FIRST_CHAR_MULTIPLIER;
            }
            prev_dp[j] = Some((score, j)); // begin = j
        }
    }

    // Iterate for i=1..m-1
    for i in 1..m {
        let mut curr_dp: Vec<Option<(i32, usize)>> = vec![None; n];
        let mut best_prev_score = None;
        let mut best_prev_idx = 0;
        let mut last_best_gap = 0;
        // We need to iterate j from 0..n and maintain best previous dp up to j-1
        // For each j where pat[i] matches text[j], we compute best score from any k < j
        // Score = dp_prev[k].score + gap penalty + SCORE_MATCH + bonus[j] + consecutive bonus if applicable
        // Gap penalty: if there is gap between k and j, penalty = SCORE_GAP_START + (gap-1)*SCORE_GAP_EXTENSION
        // Consecutive: if j == k+1, add BONUS_CONSECUTIVE

        let mut best_score_so_far: Option<(i32, usize, usize)> = None; // (score, begin, prev_k)
        // Actually we need to track best dp_prev up to j-1 to compute quickly
        // Let's do naive O(n^2) for simplicity: for each j, iterate k from 0..j-1 to find best

        for j in 0..n {
            if pat_chars[i] != text_lower[j] {
                continue;
            }
            let mut best: Option<(i32, usize)> = None;
            // Find best k < j where prev_dp[k] is Some
            for k in 0..j {
                if let Some((prev_score, begin)) = prev_dp[k] {
                    // compute gap
                    let gap = (j - k - 1) as i32;
                    let mut score = prev_score;
                    if gap == 0 {
                        score += BONUS_CONSECUTIVE;
                    } else {
                        score += SCORE_GAP_START + (gap - 1) * SCORE_GAP_EXTENSION;
                    }
                    // Add match and bonus
                    score += SCORE_MATCH + bonuses[j];
                    if let Some((cur_best, _)) = best {
                        if score > cur_best {
                            best = Some((score, begin));
                        }
                    } else {
                        best = Some((score, begin));
                    }
                }
            }
            curr_dp[j] = best;
        }
        prev_dp = curr_dp;
    }

    // After processing all pattern chars, find best score among prev_dp (which corresponds to last pattern char)
    let mut best: Option<(i32, usize, usize)> = None; // score, begin, end
    for j in 0..n {
        if let Some((score, begin)) = prev_dp[j] {
            let end = j;
            if let Some((best_score, _, _)) = best {
                if score > best_score {
                    best = Some((score, begin, end));
                }
            } else {
                best = Some((score, begin, end));
            }
        }
    }

    if let Some((score, begin, end)) = best {
        // Also need to consider length? The score already includes bonuses
        Some((score, begin, end))
    } else {
        None
