fn parse_config_from_env_and_args(cli_args: &[String]) -> Result<(Config, Vec<String>, Option<String>), String> {
    // Returns config, remaining args (special flags precedence list), and error if any
    // Also need to handle special flags: --help, --version, --bash, --zsh, --fish, --man
    // We need to collect special flags in order of appearance across file, env, cli
    // The order matters for precedence: later overrides earlier? From earlier test, last special flag wins.
    // We'll build combined args list: file args + env args + cli args
    let mut combined: Vec<String> = Vec::new();
    let mut special_order: Vec<String> = Vec::new();

    // File
    if let Ok(file_path) = env::var("FZF_DEFAULT_OPTS_FILE") {
        if !file_path.is_empty() {
            let content = fs::read_to_string(&file_path).map_err(|e| format!("$FZF_DEFAULT_OPTS_FILE: open {}: {}", file_path, e))?;
            // The file contains options separated by whitespace? Or lines? From docs: file to read default options from. Might be like env var: shell-like?
            // We need to parse file content similarly to env var? The file we tested had newline separated but also space separated worked.
            // The content may include newlines. We should parse using shlex.
            let file_args = match shlex::split(&content) {
                Some(v) => v,
                None => return Err(format!("{}: invalid command line string", file_path)),
            };
            for arg in &file_args {
                if arg == "--help" || arg == "--version" || arg == "--bash" || arg == "--zsh" || arg == "--fish" || arg == "--man" || arg == "-h" || arg == "-v" || arg.starts_with("--help=") || arg.starts_with("--version") {
                    special_order.push(arg.clone());
                }
            }
            combined.extend(file_args);
        }
    }

    // Env var FZF_DEFAULT_OPTS
    if let Ok(env_opts) = env::var("FZF_DEFAULT_OPTS") {
        if !env_opts.is_empty() {
            let env_args = match shlex::split(&env_opts) {
                Some(v) => v,
                None => return Err(format!("$FZF_DEFAULT_OPTS: invalid command line string")),
            };
            for arg in &env_args {
                if arg == "--help" || arg == "--version" || arg == "--bash" || arg == "--zsh" || arg == "--fish" || arg == "--man" || arg == "-h" || arg == "-v" {
                    special_order.push(arg.clone());
                }
            }
            combined.extend(env_args);
        }
    }

    // CLI
    for arg in cli_args {
        if arg == "--help" || arg == "--version" || arg == "--bash" || arg == "--zsh" || arg == "--fish" || arg == "--man" {
            special_order.push(arg.clone());
        }
    }
    combined.extend(cli_args.iter().cloned());

    // Now parse combined for config
    let mut cfg = default_config();
    // Need to handle special flags that have precedence: we will later check special_order last element
    // But we still need to parse all args for config (filter etc)
    parse_args_list(&combined, &mut cfg)?;

    // Determine which special flag wins: last in special_order
    let special = special_order.last().cloned();

    Ok((cfg, combined, special))
}

