        // Also negative indices: -1 means last field, -2 second last, etc.
        // Need to convert to 0-based inclusive range.

        let (s_idx, e_idx) = match (start, end) {
            (Some(s), Some(e)) => {
                let s_abs = if s>0 { s-1 } else { n + s };
                let e_abs = if e>0 { e-1 } else { n + e };
                (s_abs, e_abs)
            },
            (Some(s), None) => {
                let s_abs = if s>0 { s-1 } else { n + s };
                (s_abs, n-1)
            },
            (None, Some(e)) => {
                let e_abs = if e>0 { e-1 } else { n + e };
