        if s_idx <= e_idx {
            for idx in s_idx..=e_idx {
                if idx>=0 && idx < n {
                    selected.push(fields[idx as usize].clone());
                }
            }
        } else {
            // reverse range
            for idx in (e_idx..=s_idx).rev() {
                if idx>=0 && idx < n {
                    selected.push(fields[idx as usize].clone());
                }
            }
        }
    }
    selected
}

