fn parse_isize(s: &str) -> Result<isize, String> {
    s.parse::<isize>().map_err(|_| format!("invalid format: {}", s))
}

fn parse_range_expr(s: &str) -> Result<FieldRange, String> {
    if s.is_empty() {
        return Err(format!("invalid format: {}", s));
    }
    if s.contains("..") {
        let parts: Vec<&str> = s.split("..").collect();
        if parts.len() != 2 {
            return Err(format!("invalid format: {}", s));
        }
        let left = parts[0];
        let right = parts[1];
        let start = if left.is_empty() { None } else { Some(parse_isize(left)?) };
        let end = if right.is_empty() { None } else { Some(parse_isize(right)?) };
        if let Some(v) = start {
            if v == 0 { return Err(format!("invalid format: {}", s)); }
        }
        if let Some(v) = end {
            if v == 0 { return Err(format!("invalid format: {}", s)); }
        }
        Ok(FieldRange { start, end })
    } else {
        let v = parse_isize(s)?;
        if v == 0 { return Err(format!("invalid format: {}", s)); }
        Ok(FieldRange { start: Some(v), end: Some(v) })
    }
}

fn parse_field_list(s: &str) -> Result<Vec<FieldRange>, String> {
    if s.is_empty() {
        return Err(format!("invalid format: {}", s));
    }
    let mut res = Vec::new();
    for part in s.split(',') {
        if part.is_empty() {
            return Err(format!("invalid format: {}", s));
        }
        res.push(parse_range_expr(part.trim())?);
    }
    Ok(res)
}

fn extract_placeholders(s: &str) -> Vec<String> {
    let mut res = Vec::new();
    let mut chars = s.char_indices().peekable();
    let mut start: Option<usize> = None;
    for (i, c) in s.char_indices() {
        if c == '{' {
            start = Some(i);
        } else if c == '}' {
            if let Some(st) = start {
                let inner = &s[st+1..i];
                res.push(inner.to_string());
                start = None;
            }
        }
    }
    res
}

fn is_valid_placeholder(inner: &str) -> bool {
    let mut s = inner.trim();
    if s.is_empty() { return false; }
    if s.starts_with('+') { s = &s[1..]; }
    if s == "n" || s == "q" || s == "u" { return true; }
    // try parse as field range
    if let Ok(_) = parse_range_expr(s) { return true; }
    false
}

fn parse_with_nth(s: &str) -> Result<WithNth, String> {
    if s.is_empty() {
        return Err(format!("template should include at least 1 placeholder: {}", s));
    }
    if s.contains('{') {
        let placeholders = extract_placeholders(s);
        if !placeholders.iter().any(|ph| is_valid_placeholder(ph)) {
            return Err(format!("template should include at least 1 placeholder: {}", s));
        }
        return Ok(WithNth::Template(s.to_string()));
    }
    match parse_field_list(s) {
        Ok(v) => Ok(WithNth::Fields(v)),
        Err(_) => Err(format!("template should include at least 1 placeholder: {}", s)),
    }
}

fn parse_accept_nth(s: &str) -> Result<AcceptNth, String> {
    if s.is_empty() {
        return Err(format!("template should include at least 1 placeholder: {}", s));
    }
    if s.contains('{') {
        let placeholders = extract_placeholders(s);
        if !placeholders.iter().any(|ph| is_valid_placeholder(ph)) {
            return Err(format!("template should include at least 1 placeholder: {}", s));
        }
        return Ok(AcceptNth::Template(s.to_string()));
    }
    match parse_field_list(s) {
        Ok(v) => Ok(AcceptNth::Fields(v)),
        Err(_) => Err(format!("template should include at least 1 placeholder: {}", s)),
    }
}

fn parse_scheme(s: &str) -> Result<Scheme, String> {
    match s {
        "default" => Ok(Scheme::Default),
        "path" => Ok(Scheme::Path),
        "history" => Ok(Scheme::History),
        "" => Err(format!("invalid scoring scheme:  (expected: default|path|history)")),
        _ => Err(format!("invalid scoring scheme: {} (expected: default|path|history)", s)),
    }
}

fn parse_algo(s: &str) -> Result<Algo, String> {
    match s {
        "v1" => Ok(Algo::V1),
        "v2" => Ok(Algo::V2),
        "" => Err(format!("invalid algorithm (expected: v1 or v2)")),
        _ => Err(format!("invalid algorithm (expected: v1 or v2)")),
    }
}

fn parse_tiebreak(s: &str) -> Result<Vec<Tiebreak>, String> {
    if s.is_empty() {
        return Err(format!("invalid sort criterion:"));
    }
    let mut seen = HashSet::new();
    let mut res = Vec::new();
    for part in s.split(',') {
        let p = part.trim();
        if p.is_empty() {
            return Err(format!("invalid sort criterion:"));
        }
        let tb = match p {
            "length" => Tiebreak::Length,
            "chunk" => Tiebreak::Chunk,
            "pathname" => Tiebreak::Pathname,
            "begin" => Tiebreak::Begin,
            "end" => Tiebreak::End,
            "index" => Tiebreak::Index,
            _ => return Err(format!("invalid sort criterion: {}", p)),
        };
        if !seen.insert(p.to_string()) {
            return Err(format!("duplicate sort criteria: {}", p));
        }
        res.push(tb);
    }
    if let Some(pos) = res.iter().position(|x| *x == Tiebreak::Index) {
        if pos != res.len()-1 {
            return Err(format!("index should be the last criterion"));
        }
    }
    Ok(res)
}

