    // Let's implement: if ignore_case None (smart), then check if original query (or any term) contains uppercase, then case_sensitive = true, else false.
    // For now, we pass case_sensitive boolean computed outside per query.

    // We'll compute best group

    let mut best: Option<(i32, usize, usize, usize, usize, usize)> = None; // score, begin, end, len, chunk, pathname_bonus?

    for group in groups {
        if group.is_empty() {
            // matches everything
            let score = 0;
            if best.is_none() || score > best.as_ref().unwrap().0 {
                best = Some((score, 0,0, line.chars().count(), 0, 0));
            }
            continue;
        }

        let mut total_score = 0;
        let mut first_begin = usize::MAX;
        let mut last_end = 0;
        let mut min_begin = usize::MAX;
        let mut max_end = 0;
        let mut group_match = true;
        let mut chunk_len_sum = 0;
        let mut term_count = 0;

        // For tiebreak pathname: need to know if match is in pathname tail?
        let mut pathname_score = 0;

        for term in group {
            let case_sensitive = case_global; // for smart-case, this is determined based on if term contains uppercase? We'll compute per term?

            // Actually smart-case: if term contains uppercase, case_sensitive true, else false. But for simplicity, use global determined

            let res = if term.fuzzy {
