            } else {
                exact_match_term(term, line, case_sensitive, literal).map(|(s,b,e)| (s,b,e,0,0))
            };

            if term.negated {
                // negated term should NOT match
                if res.is_some() {
                    group_match = false;
                    break;
                } else {
                    // negated non-match contributes 0 score?
                    continue;
                }
            } else {
                if let Some((score, begin, end, _len, chunk)) = res {
                    total_score += score;
                    if begin < first_begin { first_begin = begin; }
                    if end > last_end { last_end = end; }
                    if begin < min_begin { min_begin = begin; }
                    if end > max_end { max_end = end; }
                    chunk_len_sum += chunk;
                    term_count += 1;
                } else {
                    group_match = false;
                    break;
                }
            }
        }

        if group_match {
            // For empty group that matched, first_begin may still MAX
            let begin = if first_begin==usize::MAX {0} else {first_begin};
            let end = last_end;
            let len = line.chars().count();
            let chunk = if term_count>0 { chunk_len_sum / term_count } else { len };
            // total_score already sum of terms
            if best.is_none() || total_score > best.as_ref().unwrap().0 {
                best = Some((total_score, begin, end, len, chunk, pathname_score));
            }
        }
    }

    best
}

