    while i < args.len() {
        let arg = &args[i];
        if arg == "--" { break; }
        else if arg == "-e" || arg == "--exact" { cfg.exact = true; }
        else if arg == "--no-exact" { cfg.exact = false; }
        else if arg == "+x" || arg == "--no-extended" { cfg.extended = false; }
        else if arg == "-x" || arg == "--extended" { cfg.extended = true; }
        else if arg == "-i" || arg == "--ignore-case" { cfg.ignore_case = Some(true); }
        else if arg == "+i" || arg == "--no-ignore-case" { cfg.ignore_case = Some(false); }
        else if arg == "--smart-case" { cfg.ignore_case = None; }
        else if arg.starts_with("--scheme=") {
            let val = &arg["--scheme=".len()..];
            cfg.scheme = parse_scheme(val)?;
        } else if arg == "--scheme" {
            i+=1;
            if i>=args.len() { return Err(format!("invalid scoring scheme:  (expected: default|path|history)")); }
            cfg.scheme = parse_scheme(&args[i])?;
        } else if arg.starts_with("--nth=") {
            let val = &arg["--nth=".len()..];
            cfg.nth = Some(parse_field_list(val)?);
        } else if arg == "--nth" || arg == "-n" {
