        } else if arg.starts_with("--tail=") {
            let val = &arg["--tail=".len()..];
            if val.is_empty() { return Err(format!("number of items to keep required")); }
            match val.parse::<isize>() {
                Ok(n) => {
                    if n <=0 { return Err(format!("number of items to keep must be a positive integer")); }
