            // handled elsewhere
        } else if arg.starts_with("--") || arg.starts_with("+") || (arg.starts_with("-") && arg.len()>1) {
            // known options to ignore
            let known_prefixes = [
                "--height","--min-height","--tmux","--layout","--margin","--padding","--border",
                "--border-label","--border-label-pos","--list-border","--list-label","--list-label-pos",
                "--input-border","--input-label","--input-label-pos","--preview","--preview-window",
                "--preview-border","--preview-label","--preview-label-pos","--header","--header-lines",
                "--header-lines-border","--header-border","--header-label","--header-label-pos",
                "--footer","--footer-border","--footer-label","--footer-label-pos","--prompt","--pointer",
                "--marker","--marker-multi-line","--gutter","--gutter-raw","--info","--info-command",
                "--separator","--scrollbar","--jump-labels","--ellipsis","--color","--style","--multi",
                "--highlight-line","--cycle","--wrap","--wrap-sign","--raw","--track","--gap",
                "--gap-line","--freeze-left","--freeze-right","--keep-right","--scroll-off","--hscroll-off",
                "--filepath-word","--tabstop","--with-shell","--listen","--walker","--history",
                "--bind","--expect","--ghost","--no-bold","--no-color","--no-separator","--no-scrollbar",
                "--no-hscroll","--no-multi-line","--no-input","--no-unicode","--phony","--scheme",
                "--algo","--tiebreak","--nth","--with-nth","--accept-nth","--delimiter","--tail","--disabled",
                "--read0","--print0","--ansi","--sync","--query","--select-1","--exit-0","--filter",
                "--print-query","--tac","--literal","--no-literal","--no-sort","--sort","--exact","--no-exact",
                "--extended","--no-extended","--ignore-case","--no-ignore-case","--smart-case",
            ];
            let mut known = false;
            let base = if let Some(pos) = arg.find('=') { &arg[..pos] } else { arg.as_str() };
            for kp in &known_prefixes {
                if base == *kp || arg.starts_with(kp) {
                    known = true;
                    break;
                }
            }
            if !known {
                return Err(format!("unknown option: {}", arg));
            }
        }
        i+=1;
    }
    Ok(())
}

fn parse_config() -> Result<(Config, Option<String>), String> {
    let cli_args: Vec<String> = env::args().skip(1).collect();
    let mut combined: Vec<String> = Vec::new();
    let mut special_order: Vec<String> = Vec::new();

    // file
    if let Ok(file_path) = env::var("FZF_DEFAULT_OPTS_FILE") {
        if !file_path.is_empty() {
            let content = fs::read_to_string(&file_path).map_err(|e| format!("$FZF_DEFAULT_OPTS_FILE: open {}: {}", file_path, e.to_string()))?;
            let file_args = shlex::split(&content).ok_or_else(|| format!("{}: invalid command line string", file_path))?;
            for arg in &file_args {
                if ["--help","--version","--bash","--zsh","--fish","--man"].contains(&arg.as_str()) {
                    special_order.push(arg.clone());
                }
            }
            combined.extend(file_args);
        }
    }
    if let Ok(env_opts) = env::var("FZF_DEFAULT_OPTS") {
        if !env_opts.is_empty() {
            let env_args = shlex::split(&env_opts).ok_or_else(|| format!("$FZF_DEFAULT_OPTS: invalid command line string"))?;
            for arg in &env_args {
                if ["--help","--version","--bash","--zsh","--fish","--man"].contains(&arg.as_str()) {
                    special_order.push(arg.clone());
                }
            }
            combined.extend(env_args);
        }
    }
    for arg in &cli_args {
        if ["--help","--version","--bash","--zsh","--fish","--man"].contains(&arg.as_str()) {
            special_order.push(arg.clone());
        }
    }
    combined.extend(cli_args.clone());

    let mut cfg = default_config();
    parse_args_list(&combined, &mut cfg)?;

    // check special flags in combined order already captured, but need to find last special in combined that includes file/env/cli
    // We already have special_order from file+env+cli, last wins
    let special = special_order.last().cloned();

    // Additionally, if filter is still None but query present? In original, filter overrides query for output, but query alone without filter should still be considered filter? No, query is for interactive.
    // For our filter mode, we use cfg.filter. If filter is empty string, that means show all.

    Ok((cfg, special))
}

// Helpers for fields

fn get_fields(line: &str, delim: &Option<regex::Regex>) -> Vec<String> {
    if let Some(re) = delim {
        // if regex is empty string, it matches everywhere? The split will produce many empty? But we will handle: if pattern empty, return whole line as single field? For simplicity, if re.as_str().is_empty() then return vec![line.to_string()]?
        if re.as_str().is_empty() {
            return vec![line.to_string()];
        }
        re.split(line).map(|s| s.to_string()).collect()
    } else {
        // AWK
        if line.trim().is_empty() {
            return Vec::new();
        }
        line.split_whitespace().map(|s| s.to_string()).collect()
    }
}

fn extract_ranges(fields: &[String], ranges: &[FieldRange]) -> Vec<String> {
    let n = fields.len() as isize;
    if n==0 { return Vec::new(); }
    let mut out = Vec::new();
    for r in ranges {
        let (s_idx, e_idx) = match (r.start, r.end) {
            (Some(s), Some(e)) => {
                let sa = if s>0 { s-1 } else { n + s };
                let ea = if e>0 { e-1 } else { n + e };
                (sa, ea)
            },
            (Some(s), None) => {
                let sa = if s>0 { s-1 } else { n + s };
                (sa, n-1)
            },
            (None, Some(e)) => {
                let ea = if e>0 { e-1 } else { n + e };
                (0, ea)
            },
            (None, None) => (0, n-1),
        };
        if s_idx <= e_idx {
            for idx in s_idx..=e_idx {
                if idx>=0 && idx < n {
                    out.push(fields[idx as usize].clone());
                }
            }
        } else {
            for idx in (e_idx..=s_idx).rev() {
                if idx>=0 && idx < n {
                    out.push(fields[idx as usize].clone());
                }
            }
        }
    }
    out
}

fn join_fields_selected(selected: &[String], delim_str: &Option<String>) -> String {
    if let Some(d) = delim_str {
        // if delimiter is regex meta, join with space? For simplicity, if d len==1, use d, else use " "
        // But for pattern containing regex meta like "\s+" etc, we should join with space
        let is_simple = d.len()==1 || (!d.contains('\\') && !d.contains('+') && !d.contains('*') && !d.contains('[') && !d.contains('(') && !d.contains('|') && !d.contains('?') && !d.contains('^') && !d.contains('$'));
        if is_simple {
            selected.join(d)
        } else {
            // if d is like ":" or single char, use it, otherwise space
            if d == ":" || d == "," || d == ";" || d == "|" || d == "/" || d == "\\" || d == ":" {
                selected.join(d)
            } else {
                selected.join(" ")
            }
        }
    } else {
        selected.join(" ")
    }
}

fn eval_placeholder_inner(inner: &str, fields: &[String], idx: usize, delim_str: &Option<String>, _orig: &str) -> String {
    let mut s = inner.trim();
    if s.is_empty() { return String::new(); }
    let mut _plus = false;
    if s.starts_with('+') { _plus = true; s = &s[1..]; }
    if s == "n" { return idx.to_string(); }
    if s == "q" { return String::new(); }
    if let Ok(r) = parse_range_expr(s) {
        let sel = extract_ranges(fields, &[r]);
        return join_fields_selected(&sel, delim_str);
    }
    String::new()
}

fn apply_template(template: &str, fields: &[String], idx: usize, delim_str: &Option<String>, orig: &str) -> String {
    let mut res = String::new();
    let mut chars = template.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&next) = chars.peek() {
                if next == '{' || next == '}' {
                    res.push(next);
                    chars.next();
                    continue;
                }
            }
            res.push(c);
        } else if c == '{' {
            let mut inner = String::new();
            let mut closed = false;
            while let Some(ch) = chars.next() {
                if ch == '}' { closed = true; break; }
                inner.push(ch);
            }
            if closed {
                res.push_str(&eval_placeholder_inner(&inner, fields, idx, delim_str, orig));
            } else {
                res.push('{');
                res.push_str(&inner);
            }
        } else {
            res.push(c);
        }
    }
    res
}

fn get_search_text(line: &str, cfg: &Config, fields: &[String], idx: usize) -> String {
    // Apply with-nth transformation
    let transformed = if let Some(with_nth) = &cfg.with_nth {
        match with_nth {
            WithNth::Fields(ranges) => {
                let sel = extract_ranges(fields, ranges);
                join_fields_selected(&sel, &cfg.delimiter_str)
            },
            WithNth::Template(tmpl) => {
                apply_template(tmpl, fields, idx, &cfg.delimiter_str, line)
            },
        }
    } else {
        line.to_string()
    };
    transformed
}

fn get_nth_scope(search_text: &str, cfg: &Config) -> String {
    if let Some(nth_ranges) = &cfg.nth {
        // Need to split search_text into fields using delimiter
        let fields = get_fields(search_text, &cfg.delimiter);
        let sel = extract_ranges(&fields, nth_ranges);
        join_fields_selected(&sel, &cfg.delimiter_str)
    } else {
        search_text.to_string()
    }
}

// ANSI stripping
fn strip_ansi(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            if let Some(&'[') = chars.peek() {
                chars.next();
                // consume until letter
                while let Some(ch) = chars.next() {
                    if ch.is_ascii_alphabetic() { break; }
                }
            }
        } else {
            out.push(c);
        }
    }
    out
}

// Normalize latin (strip diacritics)
fn normalize_char(c: char) -> char {
    // Very simplified: map common accented e etc to base
    // Use small mapping for test cases: é è ê ë -> e, à á â ã ä -> a, etc.
    // For our purposes, we can implement using NFD stripping if we had unicode-normalization, but we removed that dep.
    // Let's implement manual mapping for common Latin letters with diacritics that appear in tests.
    match c {
        'é' | 'è' | 'ê' | 'ë' | 'ẽ' | 'ē' | 'ĕ' | 'ė' | 'ę' | 'ě' => 'e',
        'É' | 'È' | 'Ê' | 'Ë' => 'E',
        'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' => 'a',
        'À' | 'Á' | 'Â' | 'Ã' | 'Ä' | 'Å' => 'A',
        'ì' | 'í' | 'î' | 'ï' => 'i',
        'Ì' | 'Í' | 'Î' | 'Ï' => 'I',
        'ò' | 'ó' | 'ô' | 'õ' | 'ö' => 'o',
        'Ò' | 'Ó' | 'Ô' | 'Õ' | 'Ö' => 'O',
        'ù' | 'ú' | 'û' | 'ü' => 'u',
        'Ù' | 'Ú' | 'Û' | 'Ü' => 'U',
        'ç' => 'c',
        'Ç' => 'C',
        'ñ' => 'n',
        'Ñ' => 'N',
        _ => c,
    }
}

fn normalize_str(s: &str) -> String {
    s.chars().map(|c| normalize_char(c)).collect()
}

// For matching with literal false and ascii pattern, we need to consider normalization of text only?
// We'll implement helper for char equality with normalization

fn char_eq(p: char, t: char, case_sensitive: bool, literal: bool) -> bool {
    if !literal {
        // If pattern is ascii, allow matching normalized text
        // Normalize text char to base
        let t_norm = normalize_char(t);
        let p_norm = normalize_char(p);
        // If p is ascii, compare p with t_norm
        if p.is_ascii() {
            if case_sensitive {
                return p == t_norm || p == t;
            } else {
                return p.to_ascii_lowercase() == t_norm.to_ascii_lowercase() || p.to_ascii_lowercase() == t.to_ascii_lowercase();
            }
        } else {
            // pattern non-ascii: require exact match (maybe case handling)
            if case_sensitive {
                return p == t;
            } else {
                return p.to_lowercase().eq(t.to_lowercase());
            }
        }
    } else {
        if case_sensitive {
            p == t
        } else {
            p.to_lowercase().eq(t.to_lowercase())
        }
    }
}

// Fuzzy match with scoring

fn char_bonus(prev: Option<char>, curr: char, scheme: Scheme) -> i32 {
    if scheme == Scheme::History { return 0; }
    if prev.is_none() { return 10; }
    let pc = prev.unwrap();
    if scheme == Scheme::Path {
        if pc == '/' || pc == '\\' { return 10; }
        return 0;
    }
    // default
    if pc.is_whitespace() { return 10; }
    if pc == '/' { return 9; }
    if pc == ':' || pc == ';' || pc == ',' || pc == '|' { return 8; }
    if pc == '\\' { return 7; }
    if pc == '-' || pc == '_' || pc == '.' { return 6; }
    if !pc.is_alphanumeric() { return 4; }
    if pc.is_ascii_lowercase() && curr.is_ascii_uppercase() { return 7; }
    0
}

fn fuzzy_match(pattern: &str, text: &str, case_sensitive: bool, scheme: Scheme, literal: bool) -> Option<(i32, usize, usize, usize, usize)> {
    // returns (score, begin, end, match_len?, chunk?)
    if pattern.is_empty() { return Some((0,0,0,0,0)); }

    // For literal false, we already handle char_eq with normalization, but for scoring we still want bonus based on original text
    let pat_chars: Vec<char> = pattern.chars().collect();
    let txt_chars: Vec<char> = text.chars().collect();
    let n = txt_chars.len();
    let m = pat_chars.len();

    if m==0 { return Some((0,0,0,0,0)); }
    if n==0 { return None; }

    // Precompute bonuses per position
    let mut bonuses: Vec<i32> = Vec::with_capacity(n);
    for j in 0..n {
        let prev = if j==0 { None } else { Some(txt_chars[j-1]) };
        bonuses.push(char_bonus(prev, txt_chars[j], scheme));
    }

    // DP: dp_prev[j] = Some((score, begin))
    let mut dp_prev: Vec<Option<(i32, usize)>> = vec![None; n];

    for j in 0..n {
        if char_eq(pat_chars[0], txt_chars[j], case_sensitive, literal) {
            let mut score = 16 + bonuses[j];
            if j==0 { score += bonuses[j]*2; }
            dp_prev[j] = Some((score, j));
        }
    }

    for i in 1..m {
        let mut dp_cur: Vec<Option<(i32, usize)>> = vec![None; n];
        for j in 0..n {
            if !char_eq(pat_chars[i], txt_chars[j], case_sensitive, literal) { continue; }
            let mut best: Option<(i32, usize)> = None;
            for k in 0..j {
                if let Some((prev_score, begin)) = dp_prev[k] {
                    let gap = (j - k - 1) as i32;
                    let mut sc = prev_score;
                    if gap==0 {
                        sc += 8; // consecutive
                    } else {
                        sc += -3 + (gap-1)*(-1);
                    }
                    sc += 16 + bonuses[j];
                    if let Some((b,_)) = best {
                        if sc > b { best = Some((sc, begin)); }
                    } else {
                        best = Some((sc, begin));
                    }
                }
            }
            dp_cur[j] = best;
        }
        dp_prev = dp_cur;
    }

    let mut best: Option<(i32, usize, usize)> = None;
    for j in 0..n {
        if let Some((score, begin)) = dp_prev[j] {
            if let Some((bs,_,_)) = best {
                if score > bs { best = Some((score, begin, j)); }
            } else {
                best = Some((score, begin, j));
            }
        }
    }
    if let Some((score, begin, end)) = best {
        // compute chunk len: end-begin+1? But need whitespace delimited chunk?
        // For chunk tiebreak: chunk is matched chunk delimited by whitespaces? The matched chunk is from first to last matched char inclusive? Then its length includes gaps. But "chunk" tiebreak prefers shorter matched chunk delimited by whitespace?
        // For simplicity, chunk len = end-begin+1
        let chunk = end - begin + 1;
        // for length tiebreak, we need original line length
        // pathname etc handled elsewhere
        Some((score, begin, end, txt_chars.len(), chunk))
    } else {
        None
    }
}

#[derive(Debug, Clone)]
struct RichTerm {
    raw: String,
    text: String,
    fuzzy: bool,
    prefix: bool,
    suffix: bool,
    boundary: bool,
    negated: bool,
}

fn parse_query(query: &str, extended: bool, exact: bool) -> Vec<Vec<RichTerm>> {
    if !extended {
        let fuzzy = !exact;
        return vec![vec![RichTerm { raw: query.to_string(), text: query.to_string(), fuzzy, prefix: false, suffix: false, boundary: false, negated: false }]];
    }

    let mut tokens: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut chars = query.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&' ') = chars.peek() {
                cur.push(' ');
                chars.next();
            } else {
                cur.push(c);
            }
        } else if c == ' ' {
            if !cur.is_empty() {
                tokens.push(cur.clone());
                cur.clear();
            }
            while let Some(&' ') = chars.peek() { chars.next(); }
        } else {
            cur.push(c);
        }
    }
    if !cur.is_empty() { tokens.push(cur); }

