fn exact_match_term(term: &RichTerm, text: &str, case_sensitive: bool, literal: bool) -> Option<(i32, usize, usize)> {
    // Returns score, begin, end if matches
    // Handles exact, prefix, suffix, boundary
    let pat = &term.text;
    if pat.is_empty() { return Some((0,0,0)); }

    // For case handling and literal/normalization: we need to implement matching that respects normalization for ascii patterns?
    // For exact matching, should normalization also apply? Earlier test: "e" matches "é" in exact mode? Let's test: we had exact mode test for "foo" etc. For "e" vs "é" with exact, does it match?
