    // We'll implement exact matching with normalization similar to fuzzy: use char_eq logic but require contiguous substring, not subsequence.

    // Approach: search for substring where each char matches via char_eq

    let pat_chars: Vec<char> = pat.chars().collect();
    let txt_chars: Vec<char> = text.chars().collect();
    let n = txt_chars.len();
    let m = pat_chars.len();
    if m > n { return None; }

    // For each possible start position
    for start in 0..=n-m {
        let mut ok = true;
        for k in 0..m {
            if !char_eq(pat_chars[k], txt_chars[start+k], case_sensitive, literal) {
                ok = false;
                break;
            }
        }
        if !ok { continue; }

        // Check prefix condition
        if term.prefix {
            if start !=0 { continue; }
        }
        if term.suffix {
            if start + m != n { continue; }
        }
        if term.boundary {
            // Need word boundaries at both ends
            let before = if start==0 { None } else { Some(txt_chars[start-1]) };
            let after = if start+m >= n { None } else { Some(txt_chars[start+m]) };
            // is_word_boundary: true if None or not alphanumeric (including underscore? But underscore considered boundary per doc)
            // However doc says underscore is considered word boundary but ranked lower.
            let before_is_boundary = match before {
                None => true,
                Some(c) => !c.is_alphanumeric(),
            };
            let after_is_boundary = match after {
                None => true,
                Some(c) => !c.is_alphanumeric(),
            };
            if !before_is_boundary || !after_is_boundary { continue; }
            // compute boundary rank for scoring
            let before_is_underscore = before == Some('_');
            let after_is_underscore = after == Some('_');
            let rank = match (before_is_underscore, after_is_underscore) {
                (false,false) => 0,
                (false,true) | (true,false) => 1,
                (true,true) => 2,
            };
            // Score higher for lower rank
            let score = 1000 - rank*10 - start as i32;
            return Some((score, start, start+m-1));
        } else {
            // For exact without boundary, score based on position: earlier better
            let score = 1000 - start as i32;
            return Some((score, start, start+m-1));
        }
    }
    None
}

