fn match_line_extended(line: &str, and_groups: &[Vec<RichTerm>], case_global: bool, scheme: Scheme, literal: bool) -> Option<(i32, usize, usize, usize, usize, usize)> {
    // and_groups: outer is AND, inner is OR
    if and_groups.is_empty() {
        return Some((0,0,0,line.chars().count(),0,0));
    }

    let mut total_score = 0;
    let mut first_begin = usize::MAX;
    let mut last_end = 0;
    let mut chunk_sum = 0;
    let mut term_cnt = 0;

    for or_group in and_groups {
        if or_group.is_empty() {
            continue;
        }
        // For this AND group, need at least one OR term to satisfy
        let mut best_in_group: Option<(i32, usize, usize, usize)> = None; // score, begin, end, chunk

        for term in or_group {
            let res = if term.fuzzy {
                fuzzy_match(&term.text, line, case_global, scheme, literal)
            } else {
                exact_match_term(term, line, case_global, literal).map(|(s,b,e)| (s,b,e,0,0))
            };

            if term.negated {
                // For negated term, satisfaction is when res is None (line does NOT contain term)
                if res.is_none() {
                    // Negated term satisfied, contributes 0 score? Could give some score but we treat as 0
                    // For OR group, if this negated term is satisfied, then the whole AND group is satisfied (since at least one OR alternative satisfied)
                    // We'll consider its score as 0 and begin/end as 0 for tiebreak? We need to not affect begin/end too much.
                    // To make OR group satisfied, we can set best_in_group to Some with 0 score if not already satisfied by a positive term with higher score
                    // For simplicity, if we find a negated term that is satisfied, we consider group satisfied with 0 score unless there is a positive term with higher score
                    if best_in_group.is_none() {
                        best_in_group = Some((0, 0, 0, 0));
                    }
                    // Continue to check other OR terms that might have higher score
                } else {
                    // This particular negated term not satisfied (line contains the term), so this OR alternative fails, but other OR alternatives might still satisfy
                    continue;
