                        };
                        let b_in_tail = match b_last_opt {
                            None => 1,
                            Some(pos) => if b.begin > pos { 1 } else { 0 },
                        };
                        if a_in_tail != b_in_tail {
                            return b_in_tail.cmp(&a_in_tail);
                        }
                    },"""

